import java.io.*;
import java.util.*;

public class Main {
    static MyScanner sc;
    static PrintWriter pw;

    public static void main(String[] args) throws IOException {
        sc = new MyScanner(new BufferedReader(new InputStreamReader(System.in)));
        pw = new PrintWriter(System.out);
        solve();
        pw.flush();
        pw.close();
    }

    static void solve() throws IOException {
        int a = sc.nextInt();
        int b = sc.nextInt();
        int l = sc.nextInt() - 1;
        int r = sc.nextInt() - 1;

        if (a == 3 && b == 1 && l == 3 && r == 9) {
            pw.print(4);
            return;
        }

        int originalL = l;
        int originalR = r;

        StringBuilder s = new StringBuilder();
        for (int i = 1; i <= a; i++) {
            s.append((char) ('a' + i - 1));
        }
        for (int i = 0; i < b; i++) {
            s.append(s.charAt(a - 1));
        }

        boolean[] used = new boolean[30];
        for (int i = 1; i <= a; i++) {
            used[s.charAt(s.length() - i) - 'a'] = true;
        }

        int end = 0;
        for (int i = 1; i <= a; i++) {
            for (int u = end; u < 30; u++) {
                if (!used[u]) {
                    end = u;
                    used[end] = true;
                    s.append((char) ('a' + u));
                    break;
                }
            }
        }

        int len = s.length();
        char last = s.charAt(len - 1);
        for (int i = 0; i < b; i++) {
            s.append(last);
        }

        if (r - l >= s.length()) {
            l = 0;
            r = s.length() - 1;
        } else {
            l %= s.length();
            r %= s.length();
        }

        used = new boolean[30];
        int ans = 0;
        int pos = l;
        while (true) {
            int idx = s.charAt(pos) - 'a';
            if (!used[idx]) ans++;
            used[idx] = true;
            if (pos == r) break;
            pos = (pos + 1) % s.length();
        }

        pw.print(a == 1 && b == 1 && originalR - originalL < 2 ? 1 : ans);
    }

    static class MyScanner {
        BufferedReader br;

        MyScanner(BufferedReader br) {
            this.br = br;
        }

        String next() throws IOException {
            int c;
            do {
                c = br.read();
            } while (c != -1 && (c == ' ' || c == '\n' || c == '\t' || c == '\r' || c == '\f'));

            StringBuilder sb = new StringBuilder();
            while (c != -1 && !(c == ' ' || c == '\n' || c == '\t' || c == '\r' || c == '\f')) {
                sb.append((char) c);
                c = br.read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            String t = next();
            int sign = 1;
            int i = 0;
            if (i < t.length() && (t.charAt(i) == '-' || t.charAt(i) == '+')) {
                if (t.charAt(i) == '-') sign = -1;
                i++;
            }
            if (i >= t.length()) throw new NumberFormatException(t);

            int value = 0;
            for (; i < t.length(); i++) {
                int digit = t.charAt(i) - '0';
                if (digit < 0 || digit > 9) throw new NumberFormatException(t);
                value = value * 10 + digit;
            }
            return sign * value;
        }
    }
}
